ll i,n,x,y;

ll gcd(int x,int y){
 int p = x % y;
 x = y;
 y = p;
if(y > 0)x = gcd(x,y);
return x;
}

ll lcm(int x,int y){
return ll(x) * ll(y) / gcd(x,y);
}

ld func(int x1,int y1,int x2,int y2){
ll s = lcm(y1,y2);
ll s1 = abs(s / y1 * x1 - s / y2 * x2);
return ld(s1) / ld(s);
}

