cin >> x >> y >> n;
ll a = 0,b = 1; 
ld t1 = ld(x) / ld(y),h = 0;
  for(i=1;i<=n;i++){
   ll l = 1,r = 1000000,ave;
   while(r - l > 1){
    ave = (l + r) / 2;
	ld t2 = ld(ave) / ld(i);
    if(t2 < t1)l = ave;
	else r = ave;
   }
   ave = l;
   if((func(l,i,x,y) > func(r,i,x,y)))ave = r;
   if(func(ave,i,x,y)  < func(a,b,x,y)){
    a = ave;
	b = i;
   }
  }
cout << a << "/" << b;
return 0;
}
